// MARK: Waiters

@available(macOS 10.15, iOS 13.0, tvOS 13.0, watchOS 6.0, *)
extension ElementalInference {
    /// Waiter for operation ``getFeed(_:logger:)``.
    ///
    /// - Parameters:
    ///   - input: Input for operation
    ///   - logger: Logger used for logging
    @inlinable
    public func waitUntilFeedDeleted(
        _ input: GetFeedRequest,
        maxWaitTime: TimeAmount? = nil,
        logger: Logger = AWSClient.loggingDisabled
    ) async throws {
        let waiter = AWSClient.Waiter<GetFeedRequest, _>(
            acceptors: [
                .init(state: .success, matcher: AWSErrorCodeMatcher("ResourceNotFoundException")),
                .init(state: .success, matcher: try! JMESPathMatcher("status", expected: "DELETED")),
                .init(state: .retry, matcher: try! JMESPathMatcher("status", expected: "DELETING")),
                .init(state: .retry, matcher: AWSErrorCodeMatcher("InternalServerErrorException")),
                .init(state: .retry, matcher: AWSErrorCodeMatcher("TooManyRequestException")),
            ],
            minDelayTime: .seconds(3),
            command: self.getFeed
        )
        return try await self.client.waitUntil(input, waiter: waiter, maxWaitTime: maxWaitTime, logger: logger)
    }
    /// Waiter for operation ``getFeed(_:logger:)``.
    ///
    /// - Parameters:
    ///   - id: The ID of the feed to query.
    ///   - logger: Logger used for logging
    @inlinable
    public func waitUntilFeedDeleted(
        id: String,
        logger: Logger = AWSClient.loggingDisabled        
    ) async throws {
        let input = GetFeedRequest(
            id: id
        )
        try await self.waitUntilFeedDeleted(input, logger: logger)
    }
}
